const d=$input.first().json;
if(!d.episode_id) throw new Error('episode_id is required');
if(!Number.isInteger(Number(d.scene)) || Number(d.scene)<1) throw new Error('scene must be a positive integer');
if(typeof d.prompt!=='string' || !d.prompt.trim()) throw new Error('prompt is required');
if(!d.image_url || !/^https:\/\//i.test(d.image_url)) throw new Error('image_url must be an HTTPS Kling generation/upload URL');
const duration=Number(d.duration || 5);
if(!Number.isInteger(duration)||duration<3||duration>15) throw new Error('duration must be an integer from 3 to 15 seconds');
const trace=d.task_trace_id || (()=>{const ts=Date.now().toString(16).padStart(12,'0');const r=n=>Array.from({length:n},()=>Math.floor(Math.random()*16).toString(16)).join('');return `${ts.slice(0,8)}-${ts.slice(8)}-7${r(3)}-${['8','9','a','b'][Math.floor(Math.random()*4)]}${r(3)}-${r(12)}`;})();
const mcp_request={model:d.model || 'kling-video-v3_0_turbo',arguments:[{name:'prompt',value:d.prompt.trim()},{name:'duration',value:String(duration)},{name:'resolution',value:String(d.resolution || '1080p')},{name:'imageCount',value:'1'}],inputs:[{name:'first_image',inputType:'URL',url:d.image_url}],rationale:`Animate Kiko episode ${d.episode_id} scene ${d.scene} from its approved scene image for local assembly.`,taskTraceId:trace};
return [{json:{...d,scene:Number(d.scene),duration,provider:'kling_mcp',task_trace_id:trace,mcp_request}}];

const raw=$input.first().json;
const base=$('Normalize Video Request').first().json;
const payload=raw.structuredContent ?? raw.content?.find(x=>x.type==='text')?.text ?? raw;
function find(o,names){if(!o||typeof o!=='object')return undefined;for(const [k,v] of Object.entries(o)){if(names.includes(k)&&typeof v==='string'&&v)return v;}for(const v of Object.values(o)){const hit=find(v,names);if(hit)return hit;}}
const generation_id=find(payload,['generation_id','generationId']);
if(!generation_id) throw new Error('Kling video submission did not return generation_id');
return [{json:{provider:'kling_mcp',asset_type:'scene_video',episode_id:base.episode_id,scene:base.scene,duration:base.duration,generation_id,task_trace_id:base.task_trace_id,status:'submitted',submitted_at:new Date().toISOString()}}];
